          "headline": "Don't Take Our Word for It",
          "subheadline": null,
          "body": null,
          "items": [
            {
              "title": "Marcus T. \u2014 Portland, OR",
              "description": "\"I reserved my 2019 Civic on a Tuesday night and had the keys by Thursday. The inspection report was legit \u2014 no surprises. RevvLot is the real deal.\"",
              "metadata": {
                "rating": "5"
              }
            },
            {
              "title": "Priya S. \u2014 Austin, TX",
              "description": "\"Every other site felt like a trap. RevvLot showed me the actual market price right on the listing. I knew I wasn't getting played. Bought my Subaru the same week.\"",
              "metadata": {
                "rating": "5"
              }
            },
            {
              "title": "Derek W. \u2014 Chicago, IL",
              "description": "\"The $99 hold feature saved me. I found my truck on a Friday, locked it in, and closed Monday. Old-school hustle with new-school tools \u2014 exactly what the tagline says.\"",
              "metadata": {
                "rating": "5"
              }
            }
          ],
          "ctas": [],
          "asset_ideas": []
        }
      ]
